CREATE TRIGGER `trg_ratings_delete` AFTER DELETE ON `ratings` FOR EACH ROW BEGIN
  UPDATE `media`
  SET `rating` = (SELECT ROUND(COALESCE(AVG(`score`), 0), 2) FROM `ratings` WHERE `media_id` = OLD.`media_id`)
  WHERE `id` = OLD.`media_id`;
END
$$
DELIMITER ;
