INSERT INTO `media` (`id`, `slug`, `judul`, `deskripsi`, `thumbnail`, `jenis`, `jenjang`, `jenjangs`, `kelas`, `mapel`, `kompetensi_keahlian`, `link`, `embeddable`, `tags`, `status`, `rejection_note`, `contributor_id`, `contributor_name`, `views`, `rating`, `reviewed_by`, `reviewed_at`, `created_at`, `updated_at`) VALUES
('004b7a5d-2078-4bd8-bfbe-a09fb923fdac', 'materi-sistem-komputasional-kelas-x-ii-smasmkepisode-i-2x4f', 'MATERI SISTEM KOMPUTASIONAL || Kelas X II SMA/SMK/Episode I', 'ompetensi Awal\nPeserta didik memahami penggunaan komputer dan teknologi digital dalam kehidupan sehari-hari.\n\nTujuan Pembelajaran\nSetelah pembelajaran, peserta didik mampu:\n\n????Menjelaskan konsep sistem komputasional.\n????Mengidentifikasi komponen sistem komputer.\n????Menjelaskan hubungan input???process???output.\n????Menerapkan berpikir komputasional dalam menyelesaikan masalah.\n????Menyusun algoritma sederhana.\n????Membuat flowchart/pseudocode.\n????Menganalisis penerapan sistem komputasi dalam kehidupan nyata.', '/uploads/media-thumbnails/b4fc278c-c129-4da6-8378-ae945f37c3a5/1786532813-a9269580.jpg', 'Video', 'SMA', '[\"SMA\",\"SMK\"]', NULL, '', NULL, 'https://www.youtube.com/embed/bcKB4KCOEHc', 1, '[\"#InformatikaKelasX #InformatikaSMA #InformatikaSMK #FaseE #ComputationalThinking #Dekomposisi #PengenalanPola #Abstraksi #Algoritma #KurikulumMerdeka #VideoPembelajaran #BelajarInformatika #PendidikanIndonesia\"]', 'approved', NULL, 'b4fc278c-c129-4da6-8378-ae945f37c3a5', 'W. SUDARMAN', 32, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-12 11:42:49', '2026-08-12 11:06:53', '2026-10-22 09:15:50'),
('00dfb3d5-13dd-4f16-b7bc-0b1029f96ec4', 'gambar-teknik-otomotif-o3uo', 'Gambar Teknik Otomotif', 'Pembelajaran Gambar Teknik Otomotif membekali murid dengan pengetahuan dan keterampilan dasar dalam memahami, membaca, membuat, dan menginterpretasikan gambar teknik yang digunakan dalam bidang otomotif. Murid akan mempelajari fungsi dan jenis gambar teknik, standar gambar, penggunaan garis, simbol, skala, ukuran, proyeksi, serta teknik menggambar secara manual maupun menggunakan perangkat lunak desain (CAD).\n\nMelalui kegiatan pembelajaran teori dan praktik, murid dilatih untuk membaca gambar komponen dan sistem kendaraan, memahami informasi teknis dalam gambar kerja, serta membuat gambar teknik otomotif sesuai dengan standar, ketelitian, dan prosedur kerja yang berlaku di industri. Pembelajaran ini menjadi dasar penting bagi murid untuk mengembangkan kemampuan berpikir visual, ketelitian, kreativitas, dan keterampilan teknis yang dibutuhkan dalam dunia kerja otomotif.\n\nTujuan Pembelajaran:\nSetelah mempelajari Gambar Teknik Otomotif, murid diharapkan mampu memahami standar dan aturan gambar teknik, menggunakan alat gambar dengan benar, membaca dan menginterpretasikan gambar teknik otomotif, serta membuat gambar komponen otomotif secara manual maupun digital dengan memperhatikan ketepatan ukuran, simbol, skala, proyeksi, dan standar gambar teknik.', '/uploads/media-thumbnails/3b8464e2-9870-4fd9-8ff9-2784606dede2/1785731986-c20ecf19.jpg', 'Video', 'SMK', '[\"SMK\"]', 10, '', 'Teknik Otomotif', 'https://www.youtube.com/embed/VCoVFVGNCRs', 1, '[\"gambarteknik\",\"smkbisa\",\"otomotif\",\"kendaraanringan\"]', 'approved', NULL, '3b8464e2-9870-4fd9-8ff9-2784606dede2', 'ARHAM AMIRUDDIN, S.Pd., Gr.', 2, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-03 04:53:41', '2026-08-03 04:39:46', '2026-10-22 10:18:25'),
('058dbc2f-9901-4773-b6af-c81db8f457a1', 'misi-penjelajah-struktur-bangunan-ala-vr-mmmu', 'Misi Penjelajah Struktur Bangunan ala VR', 'Petunjuk & Cara Bermain \n1. Pandangan Kokpit First-Person (FPV)\nAnda berada langsung di kursi kemudi pilot pesawat luar angkasa berkecepatan tinggi. Lintasan futuristik memanjang ke depan melewati kota konstruksi megastruktur dengan 3 jalur terbang.\n2. Sensor Gerak Tangan (Hand Gesture & Palm Motion)\n- Lambaikan Tangan ke Kiri: Pesawat bergerak cepat ke Jalur Kiri.\n- Lambaikan Tangan ke Kanan: Pesawat bergerak cepat ke Jalur Kanan.\n- Angkat Telapak Tangan Tinggi: Pesawat terbang tinggi (High) untuk melewati fondasi atau mengambil kristal di atas.\n- Turunkan Tangan ke Bawah: Pesawat menunduk (Duck) untuk melewati balok melintang tinggi.\n- Tangan di Posisi Tengah: Pesawat kembali stabil di jalur tengah.\n3. Sensor Gerakan Tubuh (Body & Shoulder Lean) \n- Miring Kiri/Kanan: Memiringkan bahu atau menggeser badan memindahkan pesawat ke jalur kiri atau kanan.\n- Angkat Tangan / Tubuh Naik: Mengangkat kedua tangan menaikkan elevasi terbang.\n- Menunduk (Duck): Menekuk tubuh menurunkan pesawat.\n3. Kontrol Alternatif Keyboard & Touch\n- Tombol A / Panah Kiri: Pindah ke jalur kiri.\n- Tombol D / Panah Kanan: Pindah ke jalur kanan.\n- Tombol W / Panah Atas: Elevasi naik (High).\n- Tombol S / Panah Bawah: Menunduk (Duck).\n- Tombol Virtual Pada Layar: Tersedia untuk layar sentuh tablet/HP dan papan interaktif digital.\n4. Gerbang Kuis & Evaluasi Struktur DPIB\nSaat mendekati gerbang evaluasi, pesawat melambat. Tiga pilihan jawaban terbentang di 3 jalur. Arahkan pesawat ke gerbang jawaban yang benar berdasarkan materi konstruksi untuk memperoleh bonus skor dan menjaga energi perisai!  🏆', '/uploads/media-thumbnails/d5dfce39-5e93-4234-a7dd-0bd57726c5b8/1792210700-b73da293.jpg', 'Gim', 'SMK', '[\"SMK\"]', 10, '', 'Desain Pemodelan Dan Informasi Bangunan', 'https://structure-rocket.netlify.app/', 1, '[\"gim\",\"dpib\",\"vr\",\"elemen\",\"struktur\"]', 'pending', NULL, 'd5dfce39-5e93-4234-a7dd-0bd57726c5b8', 'TAUFIQ, S.Pd.', 0, 0.00, NULL, NULL, '2026-10-17 04:18:20', '2026-10-17 04:18:20'),
('078627f3-c987-4feb-beec-53f38c9b7bea', 'fisika-suhu-dan-kalor-tuvq', 'Fisika - Suhu dan Kalor', 'Video Pembelajaran ini bertujuan untuk membantu Siswa dan Siswi dalam melakukan Belajar Mandiri terutama dimasa pandemi yang proses belajar mengajarnya belum maksimal. Selain itu, Video Pembelajaran ini juga bertujuan untuk membantu siswa dan siswi agar lebih mudah memahami pelajaran yang sulit di mengerti hanya dalam satu kali pertemuan di dalam kelas.', '/uploads/media-thumbnails/4a1ebfa1-6a44-43a7-9743-b4787c86eee8/1785742101-2ab51df9.jpg', 'Video', 'SMA', '[\"SMA\"]', 11, 'Fisika', NULL, 'https://www.youtube.com/embed/Msxm7zmghCg', 1, '[\"Fisika\"]', 'approved', NULL, '4a1ebfa1-6a44-43a7-9743-b4787c86eee8', 'Dian', 1, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-03 13:14:31', '2026-08-03 07:28:21', '2026-10-22 10:19:06'),
('08142d7e-3d54-4f5f-ae55-e1e2260726d1', 'who-wants-to-be-a-millionaire-cj6b', 'Who Wants to Be a Millionaire', 'Game ini disusun untuk mengukur pengetahuan dasar matematika siswa yang dapat digunakan dalam assesmen diagnostik sebagai informasi awal terkait pengetahuan matematika siswa.\n ????Langkah : \n     1. Sebagai host/guru dengan sandi \"guru2026\"  lalu siapkan sesi kelas dan menyiapkan kode/token yang akan digunakan siswa untuk ikut bermain.\n    2. Sebagai peserta/siswa masuk ke kursi panas dan mulai bermain dengan cara memilih jawaban yang benar dari setiap soal. Setiap kali peserta menjawab benar akan mendapatkan hadiah yang nilainya bertingkat mulai dari 100.000 hingga 1 miliar (uang tidak hanya, hanya sebagai motivasi game). Peserta juga punya 3 pilihan bantuan, yaitu 50:50, phone a friend, dan ask the audience.\n\n\n  \n??? \n???  ????\n??? \n1.', '/uploads/media-thumbnails/ef82dc0a-6403-448b-a7d6-0154f67fe8e6/1786120926-7e3f9e3b.jpg', 'Gim', 'SD', '[\"SD\",\"SMA\",\"SMP\",\"SMK\"]', NULL, '', NULL, 'https://math-millionaire-game.lovable.app', 1, '[\"Matematika\",\"game matematika\",\"kuis matematika\",\"matematika dasar\",\"pengetahuan dasar matematika\",\"bilangan\",\"pecahan\",\"persen\",\"matematika sehari-hari\",\"matematika menyenangkan\",\"who wants to be a millionaire\"]', 'approved', NULL, 'ef82dc0a-6403-448b-a7d6-0154f67fe8e6', 'AHMAD FADLY, S.Pd., M.Pd.', 7, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-08 09:47:56', '2026-08-07 16:42:06', '2026-10-22 10:00:41'),
('0cd14b29-5772-4f93-91f1-5e543f2c3d4f', 'pembelajaran-sma-geografi-penelitian-geografi-okx1', 'Pembelajaran SMA Geografi - Penelitian Geografi', 'Video ini dibuat oleh Dinas Pendidikan dan Kebudayaan Provinsi Sulawesi Tenggara untuk membantu para pelajar yang ada di Sulawesi Tenggara dalam memahami setiap materi yang disajikan. Video ini dikemas dengan menarik dan mudah dipahami, sehingga cocok untuk pelajar dalam melakukan pembelajaran mandiri.', '/uploads/media-thumbnails/07c03cdd-426a-481e-b6ca-cb1860e6238c/1785742833-b630ebd7.jpg', 'Video', 'SMA', '[\"SMA\"]', 10, 'Geografi', NULL, 'https://www.youtube.com/embed/JSY-hxUx99k', 1, '[\"Pembelajaran SMA Geografi - Penelitian Geografi\"]', 'approved', NULL, '07c03cdd-426a-481e-b6ca-cb1860e6238c', 'Asmaul Husna', 2, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-03 13:14:27', '2026-08-03 07:40:33', '2026-10-22 10:11:49'),
('0dce1ef6-43b5-451d-9110-c686c5fab132', 'pembelajaran-sma-pjok-bola-voli-hsfu', 'Pembelajaran SMA PJOK - Bola Voli', 'Video ini dibuat oleh Dinas Pendidikan dan Kebudayaan Provinsi Sulawesi Tenggara untuk membantu para pelajar yang ada di Sulawesi Tenggara dalam memahami setiap materi yang disajikan. Video ini dikemas dengan menarik dan mudah dipahami, sehingga cocok untuk pelajar dalam melakukan pembelajaran mandiri.', '/uploads/media-thumbnails/07c03cdd-426a-481e-b6ca-cb1860e6238c/1785743587-fd9ffc25.jpg', 'Video', 'SMA', '[\"SMA\"]', 10, 'Pendidikan Jasmani Olahraga dan Kesehatan', NULL, 'https://www.youtube.com/embed/_6XhMZTcqGw', 1, '[\"Pembelajaran SMA PJOK - Bola Voli\"]', 'approved', NULL, '07c03cdd-426a-481e-b6ca-cb1860e6238c', 'Asmaul Husna', 1, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-03 13:14:21', '2026-08-03 07:53:07', '2026-10-22 10:11:22'),
('0e395784-af9c-428d-8716-4d90fe0495f6', 'chemlab-virtual-cn33', 'ChemLab Virtual', 'Lab virtual ini di buat sebagai salah satu bahan ajar interaktif guna memudahkan guru dalam melakukan eksperimen yang berbahaya jika di lakukan secara offline serta membantu jika alat dan bahan tidak tersedia. Selain itu Lab virtual ini juga memudahkan siswa dalam mempelajari larutan.', '/uploads/media-thumbnails/a53fa9aa-e3c3-40f1-890c-632e946f4b54/1785901579-e2a56176.jpg', 'Interaktif', 'SD', '[\"SD\",\"SMA\",\"SMK\",\"SMP\",\"PAUD\\/TK\"]', NULL, '', NULL, 'https://salnichemlab.netlify.app/', 1, '[\"chemical_solution\",\"larutan\",\"efek Tyndall\",\"koloid\",\"tekanan uap\",\"titik didih\",\"titik beku\",\"tekanan osmotik\",\"elektrolit dan non elektrolit\",\"ionisasi\"]', 'approved', NULL, 'a53fa9aa-e3c3-40f1-890c-632e946f4b54', 'SALNIATI HADE, S.Pd.,M.Si., Gr', 8, 5.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-10 13:30:34', '2026-08-05 03:46:19', '2026-10-22 10:22:30'),
('0f67b18f-9067-4397-857e-ee4d2c62bfe7', 'pai-kelas-xi-membiasakan-berpikir-kritis-semangat-mencintai-iptek-2llr', 'PAI Kelas XI || Membiasakan Berpikir Kritis & Semangat Mencintai IPTEK', 'Standar Kompetensi\n\nPeserta didik mampu memahami, menganalisis, dan menerapkan ajaran Islam tentang pentingnya berpikir kritis, melakukan tabayyun terhadap setiap informasi, serta memiliki semangat mencintai dan mengembangkan ilmu pengetahuan dan teknologi (IPTEK) sebagai bentuk tanggung jawab manusia dalam kehidupan.\n\nTujuan Pembelajaran\n\nSetelah mengikuti pembelajaran, peserta didik diharapkan mampu:\n\nMembaca dan memahami QS. Al-Hujurat/49:6 dengan baik dan benar.\nMenjelaskan arti dan kandungan QS. Al-Hujurat/49:6 tentang pentingnya melakukan tabayyun terhadap informasi.\nMenjelaskan pengertian berpikir kritis menurut perspektif Islam.\nMengidentifikasi ciri-ciri orang yang berpikir kritis dan bertanggung jawab dalam menerima informasi.\nMenjelaskan hubungan antara ajaran Islam, ilmu pengetahuan, dan teknologi (IPTEK).\nMenganalisis dampak positif dan negatif perkembangan IPTEK, khususnya dalam kehidupan sehari-hari dan media digital.\nMenerapkan prinsip tabayyun dalam memeriksa kebenaran berita atau informasi sebelum mempercayai dan menyebarkannya.\nMenunjukkan sikap kritis, objektif, bertanggung jawab, dan tidak mudah percaya terhadap informasi yang belum terbukti kebenarannya.\nMenunjukkan semangat mencintai ilmu pengetahuan dan teknologi dengan memanfaatkannya untuk hal-hal yang positif, produktif, dan sesuai dengan nilai-nilai Islam.\nMenyajikan hasil analisis terhadap suatu kasus informasi/berita di media digital dengan menerapkan prinsip berpikir kritis dan tabayyun.', '/uploads/media-thumbnails/b4fc278c-c129-4da6-8378-ae945f37c3a5/1786702996-b2d7c88a.jpg', 'Video', 'SMA', '[\"SMA\",\"SMK\"]', NULL, '', NULL, 'https://www.youtube.com/embed/japZfEgTpYU', 1, '[\"#PAIKelasXI\",\"#PAIdanBudiPekerti\",\"#AlHujurat6\",\"#Tabayyun\",\"#BerpikirKritis\",\"#IPTEK\",\"#PendidikanIslam\",\"#KurikulumMerdeka\",\"#LiterasiDigital\",\"#IslamDanIPTEK\"]', 'approved', NULL, 'b4fc278c-c129-4da6-8378-ae945f37c3a5', 'W. SUDARMAN', 11, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-15 05:18:38', '2026-08-14 10:23:16', '2026-10-22 10:13:39'),
('121d722c-e0f0-49de-8896-58601fbf30ad', 'matematika-kelas-x-trigonometri-l0lg', 'Matematika Kelas X (Trigonometri)', 'Video Pembelajaran ini bertujuan untuk memberikan media belajar mandiri siswa di rumah dan membantu guru dalam mengajar jarak jauh.', '/uploads/media-thumbnails/4a1ebfa1-6a44-43a7-9743-b4787c86eee8/1785738217-4c0894f2.jpg', 'Video', 'SMA', '[\"SMA\"]', 10, 'Pendidikan Agama dan Budi Pekerti', NULL, 'https://www.youtube.com/embed/o4wQfka7LGE', 1, '[\"Matematika\"]', 'approved', NULL, '4a1ebfa1-6a44-43a7-9743-b4787c86eee8', 'Dian', 2, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-03 06:32:00', '2026-08-03 06:23:37', '2026-10-22 10:15:14'),
('15ec5e97-b803-4d3f-a2fd-3685cea1607b', '3d-mouse-explorer-mengenal-mouse-komputer-dari-luar-hingga-ke-dalam-a5t7', '3D Mouse Explorer | Mengenal Mouse Komputer dari Luar hingga ke Dalam', '3D Mouse Explorer adalah media pembelajaran interaktif berbasis 3D yang mengajak pengguna mengeksplorasi mouse komputer dari bagian luar hingga komponen internalnya.\nPengguna dapat memutar, memperbesar, dan menjelajahi model mouse 3D menggunakan mouse komputer maupun sentuhan jari pada layar interaktif/PID.\nPelajari fungsi:\n??????? Tombol kiri & kanan\n?????? Scroll wheel\n???? Microswitch\n???? Optical sensor\n???? PCB\n???? USB interface\n??? Alur kerja mouse dari input hingga komputer\n\nMedia ini dirancang untuk pembelajaran Informatika, Teknologi, Sistem Komputer, dan Literasi Digital.', '/uploads/media-thumbnails/b4fc278c-c129-4da6-8378-ae945f37c3a5/1787670449-5e6c246e.jpg', 'Interaktif', 'SD', '[\"SD\",\"SMP\",\"SMA\",\"SMK\"]', NULL, '', NULL, 'https://3dmouse-explorer-v42.netlify.app/', 1, '[\"3D Mouse Explorer\",\"mouse komputer\",\"mouse 3D\",\"mengenal mouse\",\"bagian bagian mouse\",\"komponen mouse\",\"cara kerja mouse\",\"anatomi mouse\",\"hardware komputer\",\"perangkat input\",\"perangkat keras komputer\",\"sistem komputer\",\"informatika\",\"pembelajaran informatika\",\"media pembelajaran\",\"media pembelajaran 3D\",\"pembelajaran interaktif\",\"digital twin\",\"interactive 3D\",\"Three.js\",\"teknologi pendidikan\",\"PID\",\"papan interaktif digital\",\"laboratorium digital\",\"virtual laboratory\",\"computer mouse\",\"computer hardware\"]', 'approved', NULL, 'b4fc278c-c129-4da6-8378-ae945f37c3a5', 'W. SUDARMAN', 27, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-27 02:24:07', '2026-08-25 15:07:29', '2026-10-22 09:26:55'),
('18e1b462-f31d-4315-a368-c0abbc3511e6', 'simulasi-pesawat-prinsip-bernoulli-k2vd', 'SIMULASI PESAWAT PRINSIP BERNOULLI', 'Media untuk menampilkan aplikasi Prinsip Bernoulli pada pesawat terbang.\nTerdapat fitur untuk :\n1. Mengganti jenis badan pesawat\n2. Mengganti jenis sayap\n3. Berbagai latar simulasi\n4. Melihat penjelasan dan grafik aliran udara (Klik Tombol Penjelasan setelah simulasi selesai)', '/uploads/media-thumbnails/10da506b-37e2-4b18-b153-99b97642211d/1785811640-f1da7cc5.jpg', 'Interaktif', 'SMP', '[\"SMP\",\"SMA\"]', NULL, '', NULL, 'https://bernoulliairplane.lovable.app', 1, '[\"ipa\",\"fisika\",\"sains\",\"simulasi\",\"prinsip_bernoulli\",\"hukum_bernoulli\"]', 'approved', NULL, '10da506b-37e2-4b18-b153-99b97642211d', 'MUHAMMAD MAIL, S.Pd., Gr.', 11, 5.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-05 04:25:07', '2026-08-04 02:47:20', '2026-10-22 10:07:44'),
('194d42cb-8a37-43e2-97b2-a6df47688a76', 'bahasa-indonesia-teks-resensi-gg1c', 'Bahasa Indonesia - Teks Resensi', 'Video Pembelajaran ini bertujuan untuk membantu Siswa dan Siswi dalam melakukan Belajar Mandiri terutama dimasa pandemi yang proses belajar mengajarnya belum maksimal. Selain itu, Video Pembelajaran ini juga bertujuan untuk membantu siswa dan siswi agar lebih mudah memahami pelajaran yang sulit di mengerti hanya dalam satu kali pertemuan di dalam kelas.', '/uploads/media-thumbnails/4a1ebfa1-6a44-43a7-9743-b4787c86eee8/1785740683-7a2cbe64.jpg', 'Video', 'SMA', '[\"SMA\"]', 11, 'Bahasa Indonesia', NULL, 'https://www.youtube.com/embed/2Kn6Cxu3v5Q', 1, '[\"Bahasa Indonesia\"]', 'approved', NULL, '4a1ebfa1-6a44-43a7-9743-b4787c86eee8', 'Dian', 1, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-03 13:14:43', '2026-08-03 07:04:44', '2026-10-22 10:26:08'),
('1a88abf0-b434-48b3-b854-96d187e6fd42', 'ekonomi-pertumbuhan-dan-perkembangan-ekonomi-mgt8', 'Ekonomi - Pertumbuhan dan Perkembangan Ekonomi', 'Video Pembelajaran ini bertujuan untuk membantu Siswa dan Siswi dalam melakukan Belajar Mandiri terutama dimasa pandemi yang proses belajar mengajarnya belum maksimal. Selain itu, Video Pembelajaran ini juga bertujuan untuk membantu siswa dan siswi agar lebih mudah memahami pelajaran yang sulit di mengerti hanya dalam satu kali pertemuan di dalam kelas.', '/uploads/media-thumbnails/4a1ebfa1-6a44-43a7-9743-b4787c86eee8/1785739980-fae9ad06.jpg', 'Video', 'SMA', '[\"SMA\"]', 11, 'Ekonomi', NULL, 'https://www.youtube.com/embed/v22NP9dstF8', 1, '[\"Ekonomi\"]', 'approved', NULL, '4a1ebfa1-6a44-43a7-9743-b4787c86eee8', 'Dian', 1, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-03 13:14:51', '2026-08-03 06:53:00', '2026-10-22 10:20:55'),
