INSERT INTO `media` (`id`, `slug`, `judul`, `deskripsi`, `thumbnail`, `jenis`, `jenjang`, `jenjangs`, `kelas`, `mapel`, `kompetensi_keahlian`, `link`, `embeddable`, `tags`, `status`, `rejection_note`, `contributor_id`, `contributor_name`, `views`, `rating`, `reviewed_by`, `reviewed_at`, `created_at`, `updated_at`) VALUES
('58c26d18-13a2-40f7-93d0-57205fab1194', 'lab-massa-jenis-3d-bwro', '3D Lab - Massa Jenis', 'Jelajahi konsep massa jenis dengan cara yang lebih nyata dan interaktif!\n\nLab Massa Jenis 3D adalah media pembelajaran virtual yang memungkinkan peserta didik melakukan berbagai percobaan tentang massa jenis, gaya apung, dan sifat benda di dalam fluida melalui simulasi tiga dimensi yang realistis.\n\nPeserta didik dapat memilih berbagai jenis material dan cairan, mengubah ukuran objek, serta mengamati secara langsung apakah suatu benda akan terapung, melayang, atau tenggelam. Seluruh perhitungan fisika seperti massa, volume, massa jenis, berat, dan gaya apung ditampilkan secara otomatis sehingga proses belajar menjadi lebih mudah dipahami.\n\nFitur Utama\n???? Simulasi laboratorium 3D interaktif.\n???? Beragam jenis cairan dengan massa jenis berbeda.\n???? Koleksi material dengan karakteristik unik.\n?????? Perhitungan otomatis massa, volume, massa jenis, berat, dan gaya apung.\n???? Informasi objek ditampilkan secara real-time.\n??????? Pengaturan kualitas grafis otomatis maupun manual.\n??????? Kontrol sederhana sehingga mudah digunakan oleh semua jenjang pendidikan.\n???? Cocok sebagai media praktikum virtual saat pembelajaran IPA/Fisika.\n\nKompetensi yang Dipelajari\n1. Memahami konsep massa jenis.\n2. Menjelaskan hubungan antara massa, volume, dan massa jenis.\n3. Mengidentifikasi benda yang terapung, melayang, atau tenggelam.\n4. Memahami Hukum Archimedes melalui simulasi interaktif.\n5. Melatih kemampuan observasi, analisis, dan berpikir ilmiah.', '/uploads/media-thumbnails/76e54018-85c8-11f1-ae78-561b823daca5/1784810131-676da5b0.jpg', 'Interaktif', 'SMP', '[\"SMP\"]', 8, 'Ilmu Pengetahuan Alam (IPA)', NULL, 'https://3dlab-massajenis.afifedu.com/', 1, '[\"Lab Massa Jenis\",\"Massa Jenis\",\"Density\",\"Densitas\",\"Gaya Apung\",\"Hukum Archimedes\",\"Fluida\",\"Fisika\",\"IPA\",\"Sains\",\"Laboratorium Virtual\",\"Virtual Lab\",\"Simulasi 3D\",\"Simulasi Fisika\",\"Edukasi Interaktif\",\"Media Pembelajaran\",\"Media Interaktif\",\"Pembelajaran Digital\",\"STEM\",\"Eksperimen Virtual\",\"Praktikum Virtual\",\"Benda Terapung\",\"Benda Tenggelam\",\"Benda Melayang\",\"Massa\",\"Volume\",\"Berat\",\"Material\",\"Cairan\",\"Air\",\"Pendidikan\",\"SMP\",\"SMA\",\"Belajar Fisika\",\"Belajar IPA\",\"AfifEdu\",\"Virtual Laboratory\"]', 'approved', NULL, '76e54018-85c8-11f1-ae78-561b823daca5', 'Herwin Hamid, S.Pd, M.Pd', 183, 5.00, '76e54018-85c8-11f1-ae78-561b823daca5', '2026-07-25 14:31:36', '2026-07-23 12:35:32', '2026-10-22 09:17:25'),
('59e39660-b7ea-49c1-afb6-83640be83c50', 'interactive-stem-physics-elastisitas-dan-hukum-hooke-qtc0', 'Interactive STEM Physics Elastisitas dan Hukum Hooke', 'Materi : Elastisitas dan Hukum Hooke\nTujuan Pembelajaran : Menganalisis sifat elastisitas bahan, menerapkan Hukum Hooke pada pegas tunggal maupun susunan pegas, serta merancang solusi teknologi sederhana berbasis prinsip elastisitas melalui penyelidikan ilmiah\nPetunjuk Penggunaan Media :\n??? Klik \" Mulai Belajar\"\n??? Sentuh menu di sebelah kiri untuk berpindah halaman. \n??? Baca petunjuk penggunaan media interaktif yang sudah tersedia pada menu sebelah kiri', '/uploads/media-thumbnails/38789889-fefe-47cd-bd6c-077d8ac3fe0e/1785903763-90865e23.jpg', 'Interaktif', 'SMA', '[\"SMA\"]', 11, 'Fisika', NULL, 'https://hookes-lab-offline.lovable.app', 0, '[\"Fisika\",\"Elastisitas dan Hukum Hooke\"]', 'approved', NULL, '38789889-fefe-47cd-bd6c-077d8ac3fe0e', 'YEYEN ATUSMAN MANGIDI, S.Pd., Gr', 7, 5.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-05 04:25:16', '2026-08-05 04:22:43', '2026-10-22 10:16:49'),
