('71005836-3a02-4cb2-abba-55b8393503e0', 'pc-builder-challenge-xblh', 'PC BUILDER CHALLENGE', 'PC Builder Challenge Game adalah game simulasi interaktif yang menantang kamu untuk merancang, merakit, dan mengoptimalkan komputer dari nol! Pilih prosesor terbaik, pasang kartu grafis impian, atur sistem pendingin cair (water cooling), hingga rapikan cable management agar performa dan estetika PC kamu mencapai level maksimal.', '/uploads/media-thumbnails/b4fc278c-c129-4da6-8378-ae945f37c3a5/1786713199-c08363ee.jpg', 'Gim', 'SMA', '[\"SMA\",\"SMK\"]', NULL, '', NULL, 'https://pc-builder-challenge-game.netlify.app/', 1, '[\"#game\",\"#pcbuilder\",\"#pcbuildchallenge\",\"#custompc\",\"#pcbuild\",\"#gamingpc\",\"#pcgaming\",\"#pcsetup\",\"#pcmasterrace\",\"#tech\",\"#simulatorgame\",\"#gamer\",\"#videogames\",\"#gamingcommunity\"]', 'approved', NULL, 'b4fc278c-c129-4da6-8378-ae945f37c3a5', 'W. SUDARMAN', 12, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-15 05:18:35', '2026-08-14 13:13:19', '2026-10-22 10:13:25'),
