('c671fc66-577d-4b43-99db-796573982c3f', 'fluida-quest-87co', 'Fluida Quest', 'Media ini berisi materi fluida yang dikemas dalam bentuk menyenangkan dan berisi beberapa menu, yaitu :\n??? Materi\n??? Lab Virtual\n??? Petualangan\n??? Quiz\n??? Live Quiz\n??? Papan Skor\n\nKamu hanya tinggal masuk sebagai murid, Ketikkan nama-mu, kemudian masuk ke Dashboard and Happy Exploring.', '/uploads/media-thumbnails/10da506b-37e2-4b18-b153-99b97642211d/1785723581-c757bba8.jpg', 'Interaktif', 'SMA', '[\"SMA\"]', 11, 'Fisika', NULL, 'https://fluid-quest-fun.lovable.app', 1, '[\"fisika\",\"fluida\",\"fluda_statis\",\"fluida_dinamis\",\"archimedes\",\"pascal\"]', 'approved', NULL, '10da506b-37e2-4b18-b153-99b97642211d', 'MUHAMMAD MAIL, S.Pd., Gr.', 9, 0.00, '76e53d45-85c8-11f1-ae78-561b823daca5', '2026-08-03 02:45:11', '2026-08-03 02:19:41', '2026-10-22 10:18:38'),
